using QuickSql.Metadata;
using QuickSql.Providers;
using QuickSql.Sql;

namespace QuickSql.Providers.DuckDb;

/// <summary>DuckDB 的 DDL：血统那份 PostgreSqlCodeFirst 的克隆而不是子类——差异不在"多覆写一句"，
/// 在身份列那一格的结构形态：血统把自增写进列定义（GENERATED BY DEFAULT AS IDENTITY），本家那一格是
/// 句外的序列（CREATE SEQUENCE 先发、列里再挂 DEFAULT nextval('…')），换掉的是 EmitCreateTable 的形状。
/// 标识符策略照 PostgreSQL 原样复用（方言紧随 PG、双引号）；有一处血统没有的偏差要写死：DuckDB 的标识符
/// 大小写不敏感而保留原样（"QuickSqlOrder" 与 quicksqlorder 是同一张表），血统那颗
/// CaseSensitive_Identifiers 的"折名"判据在本家换了语义——双引号照加、不加引号也不折名，
/// "误写大小写不会静默变成另一张表"不由那一能力位保证。本类一个字都没在真库上跑过；
/// 血统里那些"PG 系…"的抛口文案在本家全部换成 DuckDB 的口径——文案是给读它的人看的，名字要能指到这一家。</summary>
public class DuckDbCodeFirst(DuckDbTypes types) : ICodeFirstDialect
{
    public IdentifierPolicy Identifiers => IdentifierPolicy.PostgreSQL;

    const string SequenceSuffix = "_seq";

    public void EmitCreateTable(SqlWriter writer, EntityContract contract)
    {
        // 身份列的字头：官方建身份表的形状就是一句 CREATE SEQUENCE 先行。
        // CREATE SEQUENCE 没有 IF NOT EXISTS：同一份脚本第二趟跑会在序列那一句上撞重名。
        foreach (var identityColumn in contract.Columns.Where(c => c.IsIdentity))
            EmitCreateSequence(writer, contract.Table, identityColumn);

        writer.Append("CREATE TABLE ");
        EmitTable(writer, contract.Table);
        writer.Append(" (");

        var parts = new List<string>(contract.Columns.Length + 1);

        foreach (var column in contract.Columns)
            parts.Add(Definition(contract.Table, column));

        if (contract.PrimaryKey.Length > 0)
        {
            var key = string.Join(", ", contract.PrimaryKey.Select(c => Identifiers.Quote(c.ColumnName)));

            parts.Add($"CONSTRAINT {Identifiers.Quote("PK_" + contract.Table.Name)} PRIMARY KEY ({key})");
        }

        writer.Append(string.Join(", ", parts)).Append(')');

        foreach (var index in contract.Indexes)
        {
            writer.Append(" ; ");
            EmitCreateIndex(writer, contract.Table, index);
        }
    }

    /// <summary>CREATE SEQUENCE 那一段：名字是带引号的字符串字面量而不是标识符——官方示例里它走单引号，
    /// 这一句不从 IdentifierPolicy 走（那一份管的是双引号），序列名里也就不存在"折名/加引号"那一条分岔。
    /// 带单引号的表/列名在本家未建模【推断】，撞上时按字面写、留给现场来拒。</summary>
    void EmitCreateSequence(SqlWriter writer, TableInfo table, ColumnContract column)
    {
        writer.Append("CREATE SEQUENCE '" + table.Name + "_" + column.ColumnName + SequenceSuffix + "'");
        writer.Append(" ; ");
    }

    /// <summary>身份列给值的那半段：DEFAULT nextval('…') 与句头那一句 CREATE SEQUENCE 引的是同一个名字
    ///（两次拼装、一次判断），漏掉任何一面，建表在场面上能过、写入直接红。</summary>
    static string NextvalLiteral(TableInfo table, ColumnContract column)
        => $"'{table.Name}_{column.ColumnName}{SequenceSuffix}'";

    public void EmitAddColumn(SqlWriter writer, TableInfo table, ColumnContract column)
    {
        // 与 EmitCreateTable 同一套前件：身份列要另发一句序列。那一档今天没有调用方
        //（结构同步只对已建表的列加列）——句头照发，出错的形状交给现场指认。
        if (column.IsIdentity)
            EmitCreateSequence(writer, table, column);

        writer.Append("ALTER TABLE ");
        EmitTable(writer, table);
        writer.Append(" ADD COLUMN ").Append(Definition(table, column));
    }

    /// <summary>血统同一格的原句照用：这一家的 ALTER COLUMN … TYPE 不碰可空性，独立一句把契约声称的
    /// 那一侧写回去。两侧 " ; " 串联——运行时执行器要么按语句拆，要么走脚本的路子。</summary>
    public void EmitAlterColumnPrecision(SqlWriter writer, TableInfo table, ColumnContract column)
    {
        var stored = types.ApplyStorageDefaults(column);

        writer.Append("ALTER TABLE ");
        EmitTable(writer, table);
        writer.Append(" ALTER COLUMN ").Append(Identifiers.Quote(column.ColumnName));
        writer.Append(" TYPE ").Append(types.GetStoreType(stored));

        writer.Append(" ; ");

        writer.Append("ALTER TABLE ");
        EmitTable(writer, table);
        writer.Append(" ALTER COLUMN ").Append(Identifiers.Quote(column.ColumnName));
        // 与建表那一句读同一格（NullableInStore），否则"改一次精度"会把值归库给的列改回可空——
        // 全站只留一条规则：DDL 里的可空性不读 IsNullable。
        writer.Append(stored.NullableInStore ? " DROP NOT NULL" : " SET NOT NULL");
    }

    public bool TryEmitColumnComment(SqlWriter writer, TableInfo table, ColumnContract column)
    {
        writer.Append("COMMENT ON COLUMN ");
        EmitTable(writer, table);
        writer.Append('.').Append(Identifiers.Quote(column.ColumnName)).Append(" IS ");
        writer.AppendStringLiteral(column.Comment ?? string.Empty, unicode: false);

        return true;
    }

    /// <summary>COMMENT ON TABLE 本身就是"设值"而不是"追加"，第二趟重发不会撞"属性已存在"
    ///（幂等在血统那份是免费的，本家照吃）；写空串等于把备注清掉——与列注释那一句同一个语义。</summary>
    public bool TryEmitTableComment(SqlWriter writer, TableInfo table, string? comment)
    {
        writer.Append("COMMENT ON TABLE ");
        EmitTable(writer, table);
        writer.Append(" IS ");
        writer.AppendStringLiteral(comment ?? string.Empty, unicode: false);

        return true;
    }

    public void EmitCreateIndex(SqlWriter writer, TableInfo table, IndexContract index)
    {
        // 与血统同一句原话：聚簇在这一家不是索引的一种，NonClustered/Clustered 都落成普通索引；
        // 全文检索要另一个访问方法加表达式，悄悄发成 btree 会建出一个查不了全文的索引。
        if (index.Kind == IndexKind.FullText)
            throw new QuickSqlException($"DuckDB 不支持 CREATE INDEX … FULLTEXT 这种写法（血统的 USING gin (to_tsvector(…)) 是 PG 那一侧的语法），尚未接线（§9.2）");

        writer.Append(index.Kind == IndexKind.Unique ? "CREATE UNIQUE INDEX " : "CREATE INDEX ");
        writer.Append(Identifiers.Quote(index.Name)).Append(" ON ");
        EmitTable(writer, table);
        writer.Append(" (");

        for (var i = 0; i < index.ColumnNames.Length; i++)
        {
            if (i > 0)
                writer.Append(',');

            writer.Append(' ').Append(Identifiers.Quote(index.ColumnNames[i]));
            writer.Append(index.Descending ? " DESC" : " ASC");
        }

        writer.Append(" )");
    }

    /// <summary>血统同一格原话：索引名按它所在的那个模式限定，DROP INDEX 吃的是带模式的独立对象名。
    /// 唯一约束不走这一句（计划层把 SchemaIndex.IsConstraint 那一条单独归进"要人工"，此处不做二次判断）。
    /// DuckDB 的索引同样是独立对象，血统那一档的前提照收。</summary>
    public bool TryEmitDropIndex(SqlWriter writer, TableInfo table, SchemaIndex index)
    {
        writer.Append("DROP INDEX ");
        writer.Append(Identifiers.Quote(table.Schema ?? "public")).Append('.');
        writer.Append(Identifiers.Quote(index.Name));

        return true;
    }

    string Definition(TableInfo table, ColumnContract column)
    {
        var writer = new SqlWriter(new(), [], '@');

        EmitColumnDefinition(writer, table, column);

        return writer.ToString();
    }

    void EmitColumnDefinition(SqlWriter writer, TableInfo table, ColumnContract column)
    {
        var stored = types.ApplyStorageDefaults(column);

        writer.Append(Identifiers.Quote(column.ColumnName)).Append(' ').Append(types.GetStoreType(stored));

        if (column.IsIdentity)
            writer.Append(" DEFAULT nextval(").Append(NextvalLiteral(table, column)).Append(')');

        // 主键列上的 NOT NULL 由表级 PRIMARY KEY 保证，但契约说它非空就得写（与血统同一句理由）。
        // 可空性读 NullableInStore：本家没有"库自己给值且永不为空"的那一型，所以这一格与 IsNullable 同值；
        // 自增列在血统走 GENERATED … AS IDENTITY，本家的那一格是 nextval——两形都是"值归库给"。
        writer.Append(stored.NullableInStore ? " NULL" : " NOT NULL");

        EmitDefault(writer, stored);
    }

    void EmitTable(SqlWriter writer, TableInfo table)
    {
        writer.Append(Identifiers.Quote(table.Schema ?? "public")).Append('.');
        writer.Append(Identifiers.Quote(table.Name));
    }

    /// <summary>列默认值（2026-11-01 那一格的 DuckDB 半边）。原生 BOOLEAN 落 TRUE/FALSE；字符串走
    /// AppendStringLiteral（反斜杠不是转义）。序列自增那一档的 DEFAULT nextval(...) 与这一格并存：
    /// identity 列的默认值在契约收尾就被拒，两者不会相撞。</summary>
    void EmitDefault(SqlWriter writer, ColumnContract column)
    {
        if (column.DefaultValue is not {} value)
            return;

        writer.Append(" DEFAULT ");

        switch (value)
        {
            case string text:
                writer.AppendStringLiteral(text, unicode: false);
                break;
            case bool flag:
                writer.Append(flag ? "TRUE" : "FALSE");
                break;
            default:
                writer.Append(ColumnDefaultText.Number(value));
                break;
        }
    }
}
